      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "Topological insulators established a fundamentally new quantum state of matter, with a remarkably clear connection between theory and protected transport experiments.",
        "attribution": "Kane and Mele provided the decisive quantum-spin-Hall theoretical framework, while Molenkamp led a landmark experimental realization.",
        "maturity": "The physics has been extensively reproduced, generalized, and has reshaped condensed-matter research over two decades.",
        "uncertainties": [
          "The wider topological-materials development involves further major theoretical and experimental contributors."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Hideo Hosono"
      ],
      "assessment": {
        "nobel_worthiness": "The iron-based superconductors opened an unexpected and durable family of high-temperature superconductors, transforming the study of correlated multiband materials.",
        "attribution": "Hosono's discovery of superconductivity in iron pnictides is a distinct and identifiable initiating contribution.",
        "maturity": "The phenomenon has been confirmed across many compounds and remains central to experimental and theoretical superconductivity.",
        "uncertainties": [
          "A complete microscopic account of unconventional pairing remains unsettled."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B035",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made the quantitative treatment of local electronic correlations in real materials possible and has become indispensable across correlated-electron physics.",
        "attribution": "Vollhardt and collaborators originated the modern framework; Georges and Kotliar made its conceptual power and practical implementations broadly decisive.",
        "maturity": "Its predictions and extensions are deeply integrated with spectroscopy, materials calculations, and experiments on correlated systems.",
        "uncertainties": [
          "The intellectual lineage includes important additional developers, particularly for numerical impurity solvers and material-specific extensions."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B055",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle graphene revealed that moiré engineering can create flat bands and highly tunable correlated quantum phases in an otherwise familiar material.",
        "attribution": "Bistritzer and MacDonald supplied the essential flat-band theory, and Jarillo-Herrero's experiments demonstrated the correlated phases compellingly.",
        "maturity": "Independent moiré platforms now support the underlying physical picture, although the detailed many-body phase diagram is still developing.",
        "uncertainties": [
          "The extent to which individual observed phases have a settled microscopic explanation remains uncertain."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature giant tunnel magnetoresistance supplied a robust quantum-transport effect with exceptional impact on magnetic-memory technology and spintronics.",
        "attribution": "Miyazaki and Moodera made central experimental demonstrations of large tunnel magnetoresistance, while Parkin was pivotal in its materials and device development.",
        "maturity": "The effect is quantitatively established, technologically deployed, and understood within mature spin-dependent tunnelling physics.",
        "uncertainties": [
          "The contribution overlaps conceptually with giant magnetoresistance, which has already received Nobel recognition.",
          "Credit across the long development of magnetic tunnel junctions requires careful delimitation."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B038",
      "proposed_laureates": [
        "David Vanderbilt",
        "Georg Kresse",
        "Peter E. Blöchl"
      ],
      "assessment": {
        "nobel_worthiness": "Ultrasoft pseudopotentials and the projector augmented-wave method made accurate first-principles simulations practical for an enormous range of materials and chemical systems.",
        "attribution": "Vanderbilt introduced ultrasoft pseudopotentials, Blöchl developed PAW, and Kresse was crucial in making these approaches reliable and widely usable.",
        "maturity": "These methods are thoroughly benchmarked and form part of the reproducible computational foundation of modern materials physics.",
        "uncertainties": [
          "The work is a powerful methodological advance rather than a single experimental discovery, and its credit landscape includes major code and algorithm developers."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B010",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks achieved a new level of control over quantum matter and frequency measurement, with fundamental and practical consequences.",
        "attribution": "Katori originated the magic-wavelength optical-lattice-clock concept, and Ye made foundational experimental and metrological advances.",
        "maturity": "Independent laboratories have achieved extraordinary performance and the clocks are approaching broad metrological deployment.",
        "uncertainties": [
          "The eventual revision of time standards and the full range of fundamental applications are still in progress."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Coherent manipulation of individual diamond spins turned a solid-state defect into a versatile quantum sensor and a compelling platform for quantum science.",
        "attribution": "Jelezko and Wrachtrup made seminal single-spin control demonstrations, while Lukin made major contributions to solid-state quantum control and sensing.",
        "maturity": "The basic physics is reproducible and the sensing applications are well established across many laboratories.",
        "uncertainties": [
          "The field has many closely connected pioneers, making a three-person attribution difficult."
        ]
      }
    }
  ]
